/**
 * Current eDamage research hide rows. A source-excluded upgrade is unavailable,
 * even when a local ROI shortcut would give it a plausible positive score.
 * These are the explicit Attack Disso comparisons in v5.11.08.10 row 2.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    damageLabHiddenByRunType
 * depends    src/mechanics/effective-paths/damage-base
 * used by    src/calculators/specs.generated, src/mechanics/effective-paths/edamage-plan
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import type { DamageRunType } from './damage-base'

const ATTACK_DISSONANCE_HIDDEN = new Set([
  'Damage', 'Damage Mastery', 'Standard Perks Bonus', 'Improve Trade-off Perks',
  'Shock Multiplier', 'Demon Mode Mastery', 'Attack Speed', 'Attack Speed Mastery',
  'Range', 'Damage / Meter', 'Range Mastery', 'Max Rend Armor Multiplier',
  'Swamp Rend', 'Ultimate Crit Mastery', 'Assist Module Substats - Cannon',
  'Assist Module Bonus - Cannon', 'Primary Module Bonus - Cannon', 'Dissonant Echo - Attack',
])

/** Whether the current source explicitly hides this research for the run type. */
export function damageLabHiddenByRunType(sheetName: string, runType: DamageRunType): boolean {
  return runType === 'Attack Disso' && ATTACK_DISSONANCE_HIDDEN.has(sheetName)
}
